<html lang="ar" dir="rtl">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>طبقات الأرض الجيولوجية</title>
<style>
  @font-face {
    font-family: 'SystemArabic';
    src: local('Segoe UI'), local('Tahoma'), local('Arial');
  }

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --crust: #8B7355;
    --mantle: #D4551A;
    --outer-core: #F0A030;
    --inner-core: #FFE066;
    --bg-deep: #0a0a1a;
    --bg-mid: #12122a;
    --text: #e8e4df;
    --text-muted: #9a9590;
    --card-bg: rgba(255,255,255,0.04);
    --card-border: rgba(255,255,255,0.08);
  }

  body {
    font-family: 'SystemArabic', Tahoma, Arial, sans-serif;
    background: var(--bg-deep);
    color: var(--text);
    line-height: 1.8;
    min-height: 100vh;
    overflow-x: hidden;
  }

  /* ── Starfield background ── */
  body::before {
    content: '';
    position: fixed;
    inset: 0;
    background:
      radial-gradient(1px 1px at 10% 20%, rgba(255,255,255,0.4), transparent),
      radial-gradient(1px 1px at 30% 65%, rgba(255,255,255,0.3), transparent),
      radial-gradient(1.5px 1.5px at 55% 15%, rgba(255,255,255,0.5), transparent),
      radial-gradient(1px 1px at 70% 80%, rgba(255,255,255,0.3), transparent),
      radial-gradient(1px 1px at 85% 40%, rgba(255,255,255,0.4), transparent),
      radial-gradient(1.5px 1.5px at 20% 90%, rgba(255,255,255,0.3), transparent),
      radial-gradient(1px 1px at 45% 50%, rgba(255,255,255,0.2), transparent),
      radial-gradient(1px 1px at 90% 10%, rgba(255,255,255,0.5), transparent),
      radial-gradient(1px 1px at 60% 45%, rgba(255,255,255,0.3), transparent),
      radial-gradient(1.2px 1.2px at 5% 55%, rgba(255,255,255,0.4), transparent);
    pointer-events: none;
    z-index: 0;
  }

  .container {
    position: relative;
    z-index: 1;
    max-width: 900px;
    margin: 0 auto;
    padding: 2rem 1.5rem 4rem;
  }

  /* ── Header ── */
  header {
    text-align: center;
    padding: 3rem 0 2rem;
  }
  header h1 {
    font-size: clamp(1.8rem, 5vw, 3rem);
    font-weight: 800;
    background: linear-gradient(135deg, var(--inner-core), var(--mantle));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 0.5rem;
  }
  header p {
    color: var(--text-muted);
    font-size: 1rem;
  }

  /* ── Earth Diagram (CSS only) ── */
  .earth-diagram {
    display: flex;
    justify-content: center;
    padding: 2rem 0 3rem;
    position: relative;
  }
  .earth-sphere {
    width: clamp(200px, 40vw, 340px);
    height: clamp(200px, 40vw, 340px);
    border-radius: 50%;
    position: relative;
    box-shadow: 0 0 60px rgba(212,85,26,0.3), 0 0 120px rgba(240,160,48,0.15), inset 0 0 40px rgba(0,0,0,0.4);
    animation: rotate-glow 8s ease-in-out infinite;
  }
  @keyframes rotate-glow {
    0%, 100% { box-shadow: 0 0 60px rgba(212,85,26,0.3), 0 0 120px rgba(240,160,48,0.15), inset 0 0 40px rgba(0,0,0,0.4); }
    50% { box-shadow: 0 0 80px rgba(212,85,26,0.4), 0 0 150px rgba(240,160,48,0.2), inset 0 0 40px rgba(0,0,0,0.4); }
  }

  /* Layer rings using box-shadow trick — each ring = layer */
  .layer-ring {
    position: absolute;
    top: 50%;
    left: 50%;
    border-radius: 50%;
    transform: translate(-50%, -50%);
  }
  .ring-inner-core {
    width: 30%;
    height: 30%;
    background: radial-gradient(circle, #fff7a0, var(--inner-core), #d4a020);
    box-shadow: 0 0 30px rgba(255,224,102,0.6);
    z-index: 4;
  }
  .ring-outer-core {
    width: 55%;
    height: 55%;
    background: radial-gradient(circle, var(--outer-core), #c8701a);
    z-index: 3;
  }
  .ring-mantle {
    width: 82%;
    height: 82%;
    background: radial-gradient(circle, var(--mantle), #8a3010);
    z-index: 2;
  }
  .ring-crust {
    width: 100%;
    height: 100%;
    background: radial-gradient(circle, var(--crust), #5a4530);
    z-index: 1;
  }

  /* Labels pointing to layers */
  .labels {
    position: absolute;
    inset: 0;
    pointer-events: none;
  }
  .label-tag {
    position: absolute;
    font-size: 0.8rem;
    font-weight: 700;
    padding: 0.25rem 0.7rem;
    border-radius: 20px;
    white-space: nowrap;
    color: #fff;
    text-shadow: 0 1px 3px rgba(0,0,0,0.6);
  }
  .label-tag::after {
    content: '';
    position: absolute;
    width: 2px;
    height: 20px;
    bottom: -22px;
    left: 50%;
    transform: translateX(-50%);
