    return f"{chr(ord('a') + f)}{r + 1}{chr(ord('a') + tf)}{tr + 1}"


def _to_fen(board: List[List[str]], active: str) -> str:
    ranks = []
    for r in range(7, -1, -1):
        rank, empty = "", 0
        for f in range(8):
            if board[r][f] == ".":
                empty += 1
            else:
                if empty:
                    rank += str(empty)
                    empty = 0
                rank += board[r][f]
        if empty:
            rank += str(empty)
        ranks.append(rank)
    return "/".join(ranks) + f" {active} - - 0 1"


def _generate_piece_moves(
    board: List[List[str]], f: int, r: int, piece: str, active: str
) -> List[str]:
    moves: List[str] = []
    pt = piece.upper()
    forward = 1 if active == "w" else -1

    def _valid(nf: int, nr: int) -> bool:
        if not (0 <= nf < 8 and 0 <= nr < 8):
            return False
        target = board[nr][nf]
        if target != "." and target.isupper() == (active == "w"):
            return False  # own piece blocks
        return True

