        nr, nf = r + forward, f
        if _valid(nf, nr) and board[nr][nf] == ".":
            moves.append(_to_uci(f, r, nf, nr))
            # Forward two from starting rank (both squares empty)
            if r == (1 if active == "w" else 6):
                nr2 = r + 2 * forward
                if _valid(f, nr2) and board[nr2][f] == ".":
                    moves.append(_to_uci(f, r, f, nr2))
        # Diagonal captures only
        for df in (-1, 1):
            nf2, nr2 = f + df, r + forward
            if _valid(nf2, nr2) and board[nr2][nf2] != ".":
