            nf2, nr2 = f + df, r + dr
            while _valid(nf2, nr2):
                moves.append(_to_uci(f, r, nf2, nr2))
                if board[nr2][nf2] != ".":
                    break  # hit a piece – captured or blocked
                nf2 += df
                nr2 += dr

