                empty += 1
            else:
                if empty:
                    rank += str(empty)
                    empty = 0
                rank += board[r][f]
        if empty:
            rank += str(empty)
        ranks.append(rank)
    return "/".join(ranks) + f" {active} {castling} - 0 1"


def _is_square_attacked(
    board: List[List[str]], f: int, r: int, by_color: str
) -> bool:
    """Is the square (f, r) attacked by any piece of by_color?"""
