def _generate_piece_moves(
    board: List[List[str]], f: int, r: int, piece: str, active: str
) -> List[str]:
    moves: List[str] = []
    pt = piece.upper()
    # board[0] is rank 8 (top), board[7] is rank 1 (bottom)
    # white moves toward rank 8 → decreasing index; black the opposite
