        if target != "." and target.isupper() == (active == "w"):
            return False  # own piece blocks
        return True

    if pt == "P":
        # Forward one square (empty only)
        nr, nf = r + forward, f
        if _valid(nf, nr) and board[nr][nf] == ".":
            moves.append(_to_uci(f, r, nf, nr))
            # Forward two from starting rank (both squares empty)
            if r == (6 if active == "w" else 1):
                nr2 = r + 2 * forward
                if _valid(f, nr2) and board[nr2][f] == ".":
