def perft(fen: str, depth: int) -> int:
    if depth == 0:
        return 1
    board, active, castling_rights = _parse_fen(fen)
    castling_moves_set: Set[str] = set(
        _castling_moves(board, active, castling_rights)
    )
    count = 0

