        if cm == "e1g1":
            new_board[7][5] = 'R'; new_board[7][7] = '.'
        elif cm == "e1c1":
            new_board[7][3] = 'R'; new_board[7][0] = '.'
        elif cm == "e8g8":
            new_board[0][5] = 'r'; new_board[0][7] = '.'
        elif cm == "e8c8":
            new_board[0][3] = 'r'; new_board[0][0] = '.'
        count += perft(
            _to_fen(new_board, _flip(active), new_castling), depth - 1
        )

    # Regular piece moves
    for f in range(8):
        for r in range(8):
            piece = board[r][f]
            if piece == ".":
                continue
            if active == "w" and piece.islower():
                continue
            if active == "b" and piece.isupper():
                continue
            for move in _generate_piece_moves(board, f, r, piece, active):
                if move in castling_moves_set:
                    continue  # already counted above
                f1, r1 = ord(move[0]) - ord('a'), 8 - int(move[1])
                f2, r2 = ord(move[2]) - ord('a'), 8 - int(move[3])
                new_board = [row[:] for row in board]
                new_board[r2][f2] = piece
                new_board[r1][f1] = '.'
                new_castling = _update_castling_rights(
                    castling_rights, piece, active, r, f
                )
                count += perft(
                    _to_fen(new_board, _flip(active), new_castling), depth - 1
                )
    return count


def _flip(color: str) -> str:
    return "b" if color == "w" else "w"

