from typing import List, Tuple, Set


def _parse_fen(fen: str) -> Tuple[List[List[str]], str, str, str]:
    """Parse FEN into (board, active_color, castling_rights, ep_target)."""
    parts = fen.split()
    board_str, active = parts[0], parts[1]
    castling_rights = parts[2] if len(parts) > 2 else "-"
    ep_target = parts[3] if len(parts) > 3 else "-"
    board: List[List[str]] = []
    for rank_str in board_str.split("/"):
        rank: List[str] = []
        for ch in rank_str:
            if ch.isdigit():
                rank.extend(["."] * int(ch))
            else:
                rank.append(ch)
        board.append(rank)
    return board, active, castling_rights, ep_target


def _to_uci(f: int, r: int, tf: int, tr: int) -> str:
    # r is 0-indexed from top of board (board[0] = rank 8 in chess)
    return f"{chr(ord('a') + f)}{8 - r}{chr(ord('a') + tf)}{8 - tr}"


def _to_fen(
    board: List[List[str]], active: str, castling: str = "-",
    ep_target: str = "-"
) -> str:
    ranks: List[str] = []
    for r in range(8):
        rank, empty = "", 0
        for f in range(8):
            if board[r][f] == ".":
                empty += 1
            else:
                if empty:
                    rank += str(empty)
                    empty = 0
                rank += board[r][f]
        if empty:
            rank += str(empty)
        ranks.append(rank)
    return "/".join(ranks) + f" {active} {castling} {ep_target} 0 1"


def _is_square_attacked(
    board: List[List[str]], f: int, r: int, by_color: str
) -> bool:
    """Is the square (f, r) attacked by any piece of by_color?"""
    # Knight
    for df, dr in ((-2, -1), (-2, 1), (-1, -2), (-1, 2),
                    (1, -2), (1, 2), (2, -1), (2, 1)):
        nf, nr = f + df, r + dr
        if 0 <= nf < 8 and 0 <= nr < 8:
            piece = board[nr][nf]
            if piece == ('N' if by_color == 'w' else 'n'):
                return True
    # Pawn
    if by_color == 'w':
        for df in (-1, 1):
            nf, nr = f + df, r - 1
            if 0 <= nf < 8 and 0 <= nr < 8 and board[nr][nf] == 'P':
                return True
    else:
        for df in (-1, 1):
            nf, nr = f + df, r + 1
            if 0 <= nf < 8 and 0 <= nr < 8 and board[nr][nf] == 'p':
                return True
    # King (adjacent)
    for df in (-1, 0, 1):
        for dr in (-1, 0, 1):
            if df == 0 and dr == 0:
                continue
            nf, nr = f + df, r + dr
            if 0 <= nf < 8 and 0 <= nr < 8:
                piece = board[nr][nf]
                if piece == ('K' if by_color == 'w' else 'k'):
                    return True
    # Rook / Queen straight
    for df, dr in ((0, 1), (0, -1), (1, 0), (-1, 0)):
        nf, nr = f + df, r + dr
        while 0 <= nf < 8 and 0 <= nr < 8:
            piece = board[nr][nf]
            if piece != '.':
                if by_color == 'w' and piece in ('R', 'Q'):
                    return True
                elif by_color == 'b' and piece in ('r', 'q'):
                    return True
                break
            nf += df
            nr += dr
    # Bishop / Queen diagonal
    for df, dr in ((1, 1), (1, -1), (-1, 1), (-1, -1)):
        nf, nr = f + df, r + dr
        while 0 <= nf < 8 and 0 <= nr < 8:
            piece = board[nr][nf]
            if piece != '.':
                if by_color == 'w' and piece in ('B', 'Q'):
                    return True
                elif by_color == 'b' and piece in ('b', 'q'):
                    return True
                break
            nf += df
            nr += dr
    return False


