    if by_color == 'w':
        for df in (-1, 1):
            nf, nr = f + df, r - 1
            if 0 <= nf < 8 and 0 <= nr < 8 and board[nr][nf] == 'P':
                return True
    else:
        for df in (-1, 1):
            nf, nr = f + df, r + 1
            if 0 <= nf < 8 and 0 <= nr < 8 and board[nr][nf] == 'p':
                return True
